import{_ as a,o,c as n,a5 as c}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"G4 — Media Package / Media Campaign (Mobile): View + Approve","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g4-package-campaign/spec.md","filePath":"mobile/features/g4-package-campaign/spec.md"}'),t={name:"mobile/features/g4-package-campaign/spec.md"};function i(d,e,p,s,r,l){return o(),n("div",null,[...e[0]||(e[0]=[c(`<h1 id="g4-—-media-package-media-campaign-mobile-view-approve" tabindex="-1">G4 — Media Package / Media Campaign (Mobile): View + Approve <a class="header-anchor" href="#g4-—-media-package-media-campaign-mobile-view-approve" aria-label="Permalink to &quot;G4 — Media Package / Media Campaign (Mobile): View + Approve&quot;">​</a></h1><p>&gt; Thuộc <code>docs/mobile/mobile-app-plan.md</code> giai đoạn G4 (xem bảng mục 3, dòng G4: &quot;Media Package/Campaign: xem + approve (Owner/Client)&quot;). &gt; File này KHÔNG phải FR chính thức — tài liệu kỹ thuật mobile bổ sung.</p><h2 id="_1-muc-tieu-pham-vi" tabindex="-1">1. Mục tiêu &amp; phạm vi <a class="header-anchor" href="#_1-muc-tieu-pham-vi" aria-label="Permalink to &quot;1. Mục tiêu &amp; phạm vi&quot;">​</a></h2><p>Mobile G4 bao gồm:</p><ol><li><strong>VIEW Media Package</strong> — danh sách package khả dụng của Workspace, chi tiết <code>WorkspaceMediaPackage</code> (negotiation status, final terms, approval timestamps 2 phía).</li><li><strong>VIEW Media Campaign</strong> — danh sách Campaign theo Workspace, chi tiết 1 Campaign: <code>strategyDetail</code>, <code>brandGuideline</code>, <code>timeline</code> (jsonb), <code>deliverablePlan</code>, <code>workItems</code>, <code>allocations</code>.</li><li><strong>APPROVE Media Campaign</strong> — cả 2 chiều Agency (OWNER/MANAGER) và Client, dùng <strong>cùng một API</strong>, phân nhánh theo role của người gọi ở server (xem mục 3).</li></ol><p><strong>Xác nhận scope &quot;view + approve&quot; only — đã verify đúng với BA:</strong> theo <code>docs/ba/04-media-package-campaign.md</code> mục 3 (3.5.5 Create Media Campaign), việc <strong>tạo</strong> Campaign là hành động của Agency dựng chiến lược chi tiết từ Package đã duyệt — không nằm trong scope mobile G4. Theo code, <code>WorkspaceCampaignController.create()</code> (POST tạo), <code>.update()</code> (PATCH sửa khi còn DRAFT) là các entrypoint ghi/soạn — <strong>không đưa vào mobile G4</strong>. Mobile G4 chỉ gọi các entrypoint đọc (list/detail) và đúng 1 entrypoint ghi duy nhất: approve.</p><p>Về Media Package: việc <strong>select/negotiate</strong> Package (FR 3.5.3) cũng là hành động ghi phức tạp (đàm phán nhiều vòng) — không đưa vào G4 mobile; G4 chỉ xem danh sách Package + xem trạng thái negotiation hiện tại của Workspace. Approve Package (FR 3.5.4) <strong>có đưa vào scope</strong> vì nằm cùng nhóm &quot;approve&quot; như Campaign — xem mục 3 và mục 6.</p><h2 id="_2-fr-tham-chieu" tabindex="-1">2. FR tham chiếu <a class="header-anchor" href="#_2-fr-tham-chieu" aria-label="Permalink to &quot;2. FR tham chiếu&quot;">​</a></h2><ul><li>FR 3.5.1 – 3.5.4 (<code>docs/ba/04-media-package-campaign.md</code> mục 2): Create/View/Request/Approve Media Package.</li><li>FR 3.5.5 – 3.5.6 (mục 3): Create/Approve Media Campaign — mobile dùng 3.5.6 (Approve) + phần &quot;view&quot; ngụ ý trong 3.5.5.</li><li>FR 3.6.9 / mục 1 file <code>05-content-task-workflow.md</code>: nguồn gốc Task — &quot;Từ Media Campaign approve&quot; là nguồn Task #1 trong backlog (xem mục 6 dưới).</li><li>Thứ tự chuẩn Workspace → Package → Campaign → Task (mục 1 của 04-media-package-campaign.md, CONFIRMED 2026-09-14).</li></ul><h2 id="_3-api-can-dung" tabindex="-1">3. API cần dùng <a class="header-anchor" href="#_3-api-can-dung" aria-label="Permalink to &quot;3. API cần dùng&quot;">​</a></h2><p>Codebase có <strong>2 controller song song</strong> cho Campaign — ground truth web (<code>brandhub-web/src/pages/campaign/services/campaignService.ts</code>) dùng <code>WorkspaceCampaignController</code>, nên mobile phải dùng route này, KHÔNG dùng <code>MediaCampaignController</code> (route <code>/api/v1/media-campaigns/...</code>, có vẻ là route cũ/dự phòng, không được web gọi).</p><p>Base path: <code>/api/v1/workspaces/{workspaceId}/campaigns</code> (<code>brandhub-business-service/src/main/java/com/brandhub/business/controller/WorkspaceCampaignController.java</code>)</p><table tabindex="0"><thead><tr><th>Hành động</th><th>Method + path</th><th>Request</th><th>Response</th></tr></thead><tbody><tr><td>List campaigns theo workspace</td><td><code>GET /api/v1/workspaces/{workspaceId}/campaigns</code></td><td>—</td><td><code>ApiResponse&lt;List&lt;MediaCampaignResponse&gt;&gt;</code></td></tr><tr><td>Xem chi tiết Campaign</td><td><code>GET /api/v1/workspaces/{workspaceId}/campaigns/{campaignId}</code></td><td>—</td><td><code>ApiResponse&lt;MediaCampaignResponse&gt;</code></td></tr><tr><td>Approve Campaign (2 phía, cùng 1 endpoint)</td><td><code>POST /api/v1/workspaces/{workspaceId}/campaigns/{campaignId}/approve</code></td><td><code>CampaignApprovalRequest { expectedVersion: Integer }</code></td><td><code>ApiResponse&lt;MediaCampaignResponse&gt;</code></td></tr><tr><td>Lịch sử feedback/review event (tham khảo, không bắt buộc G4)</td><td><code>GET /api/v1/workspaces/{workspaceId}/campaigns/{campaignId}/feedback</code></td><td>—</td><td><code>ApiResponse&lt;List&lt;CampaignReviewEvent&gt;&gt;</code></td></tr></tbody></table><p><strong>Không có 2 endpoint riêng <code>approveByAgency</code> / <code>approveByClient</code>.</strong> Chỉ có 1 endpoint <code>POST .../approve</code>. Server xác định &quot;phía&quot; (<code>AGENCY</code> hay <code>CLIENT</code>) từ chính người gọi, qua <code>CampaignWorkspaceAccess.side(workspaceId, user, write=false)</code>:</p><ul><li>role <code>OWNER</code>/<code>MANAGER</code> trong Workspace → side = <code>AGENCY</code></li><li>role <code>CLIENT</code> active trong Workspace → side = <code>CLIENT</code></li><li>Agency owner gọi trực tiếp (không qua membership) → side = <code>AGENCY</code></li></ul><p>→ Mobile <strong>không gửi</strong> cờ &quot;tôi là agency/client&quot; trong body — chỉ gửi <code>expectedVersion</code>. UI chỉ cần hiển thị đúng nút theo role đang đăng nhập (xem mục 4), server tự quyết nhánh nào được set.</p><p><code>MediaCampaignResponse</code> fields đúng tên (file <code>dto/response/MediaCampaignResponse.java</code>): <code>id, workspaceMediaPackageId, name, strategyDetail, brandGuideline, timeline, status, approvedByAgencyAt, approvedByClientAt, approvedByAgencyId, approvedByAgencyVersion, approvedByClientId, approvedByClientVersion, completedAt, completedBy, completionReason, completionTaskSummary, createdAt, updatedAt, packageTermsSnapshot, packageTermsVersion, allocationPeriod, allocations, deliverablePlan, workItems, contentVersion, workspaceId</code>.</p><p>Lưu ý quan trọng: optimistic lock dùng trong approve KHÔNG phải <code>rowVersion</code> (Hibernate <code>@Version</code>) mà là <strong><code>contentVersion</code></strong> — field business tự quản (tăng khi nội dung Campaign thay đổi). <code>CampaignApprovalRequest.expectedVersion</code> phải khớp <code>campaign.contentVersion</code> hiện tại, nếu không → lỗi <code>CAMPAIGN_VERSION_CONFLICT</code> (HTTP 409). Web gửi <code>expectedVersion: campaign.contentVersion</code> (xem <code>campaignService.ts</code> dòng <code>approve:</code>), mobile phải mirror đúng pattern này.</p><h3 id="media-package-api-view-approve" tabindex="-1">Media Package API (view + approve) <a class="header-anchor" href="#media-package-api-view-approve" aria-label="Permalink to &quot;Media Package API (view + approve)&quot;">​</a></h3><p>Base: <code>MediaPackageController.java</code></p><table tabindex="0"><thead><tr><th>Hành động</th><th>Method + path</th><th>Role</th><th>Response</th></tr></thead><tbody><tr><td>List package template toàn Admin</td><td><code>GET /api/v1/media-package-templates</code></td><td>public/any</td><td><code>List&lt;MediaPackageResponse&gt;</code></td></tr><tr><td>List package custom của Agency</td><td><code>GET /api/v1/agencies/{agencyId}/media-package-custom</code></td><td>—</td><td><code>List&lt;MediaPackageResponse&gt;</code></td></tr><tr><td>List package khả dụng của Workspace</td><td><code>GET /api/v1/workspaces/{workspaceId}/media-packages</code></td><td>OWNER/MANAGER/CLIENT</td><td><code>List&lt;MediaPackageResponse&gt;</code></td></tr><tr><td>Xem Package hiện tại của Workspace (kèm negotiation state)</td><td><code>GET /api/v1/workspaces/{workspaceId}/media-package</code></td><td>OWNER/MANAGER/CLIENT</td><td><code>WorkspaceMediaPackageResponse</code></td></tr><tr><td>Approve Package (FR 3.5.4)</td><td><code>POST /api/v1/workspaces/{workspaceId}/media-package/approve</code></td><td>OWNER/MANAGER/CLIENT</td><td><code>ApproveMediaPackageRequest</code> → <code>WorkspaceMediaPackageResponse</code></td></tr></tbody></table><p><code>WorkspaceMediaPackageResponse</code> fields: <code>workspaceMediaPackageId, workspaceId, mediaPackage, negotiationStatus, finalTerms, previousTerms, termsVersion, clientProposalCount, approvedByAgencyAt, approvedByClientAt, createdAt, updatedAt</code>. Cùng pattern dual-approval timestamp như Campaign (<code>approvedByAgencyAt</code>/<code>approvedByClientAt</code>), nhưng không thấy <code>rowVersion</code>/<code>expectedVersion</code> field tương ứng trong response — cần đọc <code>ApproveMediaPackageRequest</code> DTO thật khi implement (chưa đọc field request này, chỉ xác nhận endpoint tồn tại).</p><h2 id="_4-luong-man-hinh" tabindex="-1">4. Luồng màn hình <a class="header-anchor" href="#_4-luong-man-hinh" aria-label="Permalink to &quot;4. Luồng màn hình&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Package List (theo Workspace đang chọn)</span></span>
<span class="line"><span>  ↓ chọn 1 Workspace (nếu nhiều) → GET .../media-packages hoặc GET .../media-package</span></span>
<span class="line"><span>Package Detail (negotiation status, final terms, nút Approve nếu CLIENT/OWNER/MANAGER và chưa approve phía mình)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Campaign List (theo Workspace) → GET /api/v1/workspaces/{workspaceId}/campaigns</span></span>
<span class="line"><span>  ↓ chọn 1 Campaign</span></span>
<span class="line"><span>Campaign Detail — tabs/section:</span></span>
<span class="line"><span>  - Strategy (strategyDetail)</span></span>
<span class="line"><span>  - Brand Guideline (brandGuideline)</span></span>
<span class="line"><span>  - Timeline (parse jsonb timeline)</span></span>
<span class="line"><span>  - Deliverables (deliverablePlan + allocations + allocationPeriod)</span></span>
<span class="line"><span>  - Work Items (workItems)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Approve action — role-gated:</span></span>
<span class="line"><span>  - OWNER/MANAGER (side=AGENCY) thấy nút &quot;Agency duyệt&quot; nếu approvedByAgencyAt == null</span></span>
<span class="line"><span>  - CLIENT (side=CLIENT) thấy nút &quot;Client duyệt&quot; nếu approvedByClientAt == null</span></span>
<span class="line"><span>  - Nếu phía mình đã duyệt rồi (timestamp != null) → ẩn nút, hiện trạng thái &quot;Đã duyệt lúc ...&quot;</span></span>
<span class="line"><span>  ↓ tap Approve → confirm dialog → POST .../approve { expectedVersion: campaign.contentVersion }</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Confirmation — refetch Campaign detail, hiển thị status mới (DRAFT → APPROVED khi cả 2 phía đã duyệt)</span></span></code></pre></div><p>Màn Package Detail áp dụng pattern tương tự (approve theo <code>approvedByAgencyAt</code>/<code>approvedByClientAt</code> của <code>WorkspaceMediaPackageResponse</code>).</p><h2 id="_5-state-cache" tabindex="-1">5. State &amp; cache <a class="header-anchor" href="#_5-state-cache" aria-label="Permalink to &quot;5. State &amp; cache&quot;">​</a></h2><p>TanStack Query key gợi ý (mirror theo cách tổ chức web <code>campaignService</code>/<code>campaignDraftService</code>):</p><ul><li><code>[&#39;campaigns&#39;, workspaceId]</code> — list</li><li><code>[&#39;campaign&#39;, workspaceId, campaignId]</code> — detail</li><li><code>[&#39;workspace-media-package&#39;, workspaceId]</code> — package hiện tại của workspace</li><li><code>[&#39;media-package-templates&#39;]</code>, <code>[&#39;agency-media-package-custom&#39;, agencyId]</code></li></ul><p>Mutation approve:</p><ul><li><code>useMutation</code> gọi <code>POST .../approve</code> với <code>expectedVersion</code> lấy từ <code>contentVersion</code> <strong>đọc tại thời điểm bấm nút</strong> (không cache stale) — tốt nhất: refetch/invalidate detail ngay trước khi hiện confirm dialog, hoặc dùng <code>contentVersion</code> từ query cache hiện có và để optimistic-lock 409 làm lưới an toàn cuối.</li><li><code>onSuccess</code>: <code>invalidateQueries([&#39;campaign&#39;, workspaceId, campaignId])</code> + <code>invalidateQueries([&#39;campaigns&#39;, workspaceId])</code> (status/approvedAt đổi ảnh hưởng cả list).</li><li><code>onError</code> khi HTTP 409 (<code>CAMPAIGN_VERSION_CONFLICT</code>): đây là optimistic-lock conflict thật — nghĩa là Campaign đã bị sửa (hoặc phía kia đã duyệt) sau khi mobile load dữ liệu. Pattern mirror web: catch 409 → refetch campaign detail → hiện lại UI với <code>contentVersion</code>/<code>approvedBy*At</code> mới nhất → yêu cầu user xem lại rồi bấm Approve lần nữa (không tự động retry approve).</li><li>Server tự xử lý <strong>idempotent theo phía</strong>: nếu phía mình đã approve rồi (ví dụ double-tap, hoặc race 2 request cùng lúc từ 1 user), service trả về campaign hiện tại không lỗi (<code>if (&quot;CLIENT&quot;.equals(side) &amp;&amp; campaign.getApprovedByClientAt() != null ... return response(campaign)</code>) — mobile không cần chặn double-submit bằng debounce phức tạp, nhưng vẫn nên disable nút khi mutation đang pending (UX, không phải để tránh lỗi server).</li><li>Trường hợp khác: nếu user đã approve ở phía này rồi lại cố approve ở phía kia (ví dụ cùng 1 tài khoản vừa là approvedByAgencyId vừa cố click client-approve — hiếm, chỉ xảy ra nếu role đổi) → server trả <code>FORBIDDEN</code> (403).</li></ul><h2 id="_6-business-rules-đac-biet" tabindex="-1">6. Business rules đặc biệt <a class="header-anchor" href="#_6-business-rules-đac-biet" aria-label="Permalink to &quot;6. Business rules đặc biệt&quot;">​</a></h2><ul><li><strong>Dual approval độc lập, không theo thứ tự bắt buộc</strong>: đọc code <code>MediaCampaignServiceImpl.approveCampaign()</code> — Agency và Client có thể approve theo thứ tự bất kỳ, không ai phải chờ ai trước. Server chỉ set <code>status = APPROVED</code> khi <strong>cả 2</strong> <code>approvedByAgencyAt</code> và <code>approvedByClientAt</code> đều non-null. Trước đó status giữ <code>DRAFT</code>.</li><li><strong>CampaignStatus enum thật trong code chỉ có 4 giá trị</strong>: <code>DRAFT, APPROVED, IN_PROGRESS, COMPLETED</code> (file <code>model/enums/CampaignStatus.java</code>) — khác với liệt kê trong brief ban đầu (không có trạng thái riêng cho &quot;chờ duyệt 1 phía&quot;; trạng thái vẫn là DRAFT cho tới khi đủ 2 phía).</li><li><strong>Approve không tự sinh Task trực tiếp.</strong> Đọc kỹ <code>MediaCampaignServiceImpl</code> + <code>CampaignDeploymentServiceImpl</code>/<code>CampaignDeploymentProcessor</code>: approve chỉ chuyển <code>DRAFT → APPROVED</code>. Việc đẩy backlog Task thật xảy ra ở bước <strong>deploy</strong> riêng (<code>POST .../deploy</code>, xử lý bởi <code>CampaignDeploymentService</code>, chuyển <code>APPROVED → IN_PROGRESS</code> qua <code>CampaignDeploymentProcessor</code>). Đây là điểm khác so với mô tả BA mục 3.5.6 (&quot;Sau khi đưa chiến lược ra và cả 2 bên đồng ý → tiến hành nhấn triển khai... đẩy tự động vào Workspace&quot;) — đọc theo code, &quot;triển khai&quot; (deploy) là <strong>hành động riêng sau approve</strong>, không tự động chạy ngay khi đủ 2 approval. <strong>Deploy không thuộc scope G4</strong> (G4 chỉ view + approve) — xem mục 7.</li><li><strong>Campaign immutable sau khi rời DRAFT</strong>: <code>approveCampaign()</code> chỉ cho approve khi status là <code>DRAFT</code> hoặc <code>APPROVED</code> (để cho phép approve phía còn lại khi 1 phía đã duyệt trước, status vẫn DRAFT lúc đó — thật ra điều kiện ở code là <code>status != DRAFT &amp;&amp; status != APPROVED</code> thì throw <code>CAMPAIGN_IMMUTABLE</code>, nên campaign ở <code>IN_PROGRESS</code>/<code>COMPLETED</code> không approve được nữa, hợp lý vì đã deploy/hoàn tất).</li><li><strong>expectedVersion dùng <code>contentVersion</code>, không dùng <code>rowVersion</code>.</strong> <code>rowVersion</code> là Hibernate <code>@Version</code> dùng cho optimistic lock tầng JPA nội bộ (toàn bộ entity), còn <code>contentVersion</code> là field nghiệp vụ theo dõi số lần nội dung Campaign (strategy/timeline/deliverable) được sửa — đây mới là field dùng trong flow approve/feedback phía người dùng.</li></ul><h2 id="_7-viec-khong-lam-o-g4" tabindex="-1">7. Việc KHÔNG làm ở G4 <a class="header-anchor" href="#_7-viec-khong-lam-o-g4" aria-label="Permalink to &quot;7. Việc KHÔNG làm ở G4&quot;">​</a></h2><ul><li>Không tạo Media Campaign mới từ mobile (<code>POST .../campaigns</code> — web only).</li><li>Không sửa Campaign draft (<code>PATCH .../campaigns/{id}</code> — web only).</li><li>Không gửi feedback/góp ý Campaign (<code>POST .../feedback</code>) — cân nhắc thêm ở giai đoạn sau nếu cần, hiện để web xử lý.</li><li>Không deploy Campaign (<code>POST .../deploy</code>) — đây là hành động &quot;triển khai&quot; tạo Task backlog thật, không phải approve; để web xử lý ở G4.</li><li>Không complete/close Campaign (<code>POST .../complete</code>), không cancel Task theo Campaign.</li><li>Không request/negotiate Media Package (FR 3.5.3) từ mobile — chỉ xem + approve package.</li><li>Không tạo custom Media Package / đổi availability package (Owner-only, web).</li></ul><h2 id="_8-rui-ro-cau-hoi-mo" tabindex="-1">8. Rủi ro/câu hỏi mở <a class="header-anchor" href="#_8-rui-ro-cau-hoi-mo" aria-label="Permalink to &quot;8. Rủi ro/câu hỏi mở&quot;">​</a></h2><ol><li><strong>2 controller Campaign trùng lặp</strong> (<code>MediaCampaignController</code> route <code>/api/v1/media-campaigns/...</code> vs <code>WorkspaceCampaignController</code> route <code>/api/v1/workspaces/{workspaceId}/campaigns/...</code>) — cùng gọi <code>MediaCampaignService.approveCampaign()</code> nhưng khác path. Web chỉ dùng route thứ 2. Cần hỏi team backend route nào là chính thức/sắp deprecate để mobile không lỡ tích hợp route cũ.</li><li><code>ApproveMediaPackageRequest</code> DTO chưa đọc chi tiết field (có <code>expectedVersion</code>/version lock tương tự Campaign hay không) — cần đọc trước khi code thật phần approve Package.</li><li>BA mục 3.5.6 mô tả &quot;approve → tự động đẩy backlog&quot; nhưng code tách riêng approve/deploy — cần xác nhận với BA/PO đây là chủ định (2 bước tách biệt do an toàn) hay tài liệu BA chưa cập nhật theo code mới nhất.</li><li>Timeline, deliverablePlan, workItems là jsonb tự do (<code>String timeline</code>, <code>List&lt;PackageDeliverable&gt;</code>, <code>List&lt;CampaignWorkItem&gt;</code>) — chưa xem cấu trúc chi tiết các DTO con (<code>PackageDeliverable</code>, <code>CampaignWorkItem</code>, <code>DeliverableAllocation</code>) để thiết kế UI render chính xác từng field; cần đọc thêm khi vào giai đoạn implementation thật.</li><li>Push notification khi phía kia approve (server có gọi <code>notifyOpposite(...)</code>) — G4 doc này chưa cover tích hợp push notification mobile, nên note để G-nào-đó sau xử lý nếu cần real-time alert khi đối tác duyệt.</li></ol>`,36)])])}const m=a(t,[["render",i]]);export{h as __pageData,m as default};
